L["-- combat starts"] = "-- 戰鬥開始"
L["0 hides it (the default): it shows only while the buff is missing."] = "0 表示隱藏（預設值）：僅在增益效果缺少時顯示。"
L["0 hides it while the hand has no weapon to enchant."] = "設為0時，該手沒有可附魔的武器就會隱藏。"
L["0 hides it."] = "設為0則隱藏。"
L["0 hides it; the rules under the table can bring it back."] = "設為0則隱藏；表格下方的規則可以讓它重新顯示。"
L["0 hides the bar between casts."] = "設為0則在兩次施法之間隱藏量條。"
L["0 is normal. A higher priority wins the screen spot and is the last out of a full queue. Ties follow Overlap Behavior."] = "0 為一般。優先順序較高者會佔據畫面位置，且最後才被擠出已滿的佇列。同等時依「重疊行為」處理。"
L["1 bar"] = "1個量條"
L["1 group"] = "1個群組"
L["1 icon"] = "1個圖示"
L["1 icon in it is set to not displayed in your Cooldown Manager, so it stays out."] = "其中有1個圖示在你的技能監控中設為不顯示，所以不會加入。"
L["1 kind"] = "1種"
L["1 layout hidden here. Show it"] = "此處隱藏了 1 個版面設定。顯示它"
L["1 match"] = "1個符合"
L["1 of them is in Arc Auras already: importing again adds a second copy."] = "其中1個已在 Arc Auras 中：再次匯入會多出一份副本。"
L["1 profile"] = "1個設定檔"
L["1 reminder"] = "1個提醒"
L["1 rule"] = "1條規則"
L["1 setting differs from the group; a cyan bar marks it."] = "有1項設定與群組不同，以青色條標示。"
L["1 texture"] = "1個材質"
L["3 to 10, spot 1 at the top. Fewer spots keep what sat on the others: it comes back with more."] = "3 到 10，位置 1 在最上方。位置變少時，原本放在其他位置的內容會保留：位置增多後它們會回來。"
L["30 is a debuff's pandemic window. Needs no length."] = "30 即減益效果的災疫範圍。無需填寫持續時間。"
L[": matches again ("] = "：再次符合 ("
L["A 2.6 second timer that runs out and starts again."] = "一個 2.6 秒的計時器，結束後重新開始。"
L["A Cooldown Manager icon"] = "一個技能監控圖示"
L["A Custom Icon or Bar"] = "一個自訂圖示或自訂量條"
L["A Custom Icon or Bar's value"] = "自訂圖示或自訂量條的數值"
L["A Dynamic aura group only tracks you, your pet and your target."] = "動態光環群組只會追蹤你、你的寵物和你的目標。"
L["A Dynamic group only tracks you, your pet and your target: turn its Dynamic off."] = "動態群組只會追蹤你、你的寵物和你的目標：請關閉它的「動態」。"
L["A blank layout. Add your own groups, icons and bars."] = "空白版面設定。自行增加群組、圖示和量條。"
L["A buff or debuff as an icon; several IDs can light one icon."] = "以圖示顯示的增益或減益效果；多個 ID 可以點亮同一個圖示。"
L["A cast that finishes, one that is interrupted, then a channel."] = "一次完成的施法，一次被中斷的施法，然後是一次引導。"
L["A cast while it runs: start it over, add the seconds to what is left, leave it running, or end it."] = "計時器執行期間再次施放：重新開始、把秒數加到剩餘時間上、維持執行，或將其結束。"
L["A charge left and another coming back, over and over: the Recharging look, with its opacity, grey out, tint and glow."] = "剩餘一次使用次數，另一次正在恢復，如此循環：顯示「恢復中」樣式，含其透明度、去色、著色和發光。"
L["A condition turns off"] = "某個條件變為關閉"
L["A condition turns on"] = "某個條件變為開啟"
L["A cooldown ID names a Cooldown Manager icon, so it stays at its own spot."] = "冷卻 ID 對應技能監控圖示，所以維持在自己的位置。"
L["A cooldown ID names a Cooldown Manager icon."] = "冷卻 ID 對應技能監控圖示。"
L["A deck bar fills as the deck is drawn, with a mark for each proc."] = "牌組條隨牌組被抽取而填充，每次觸發都有一個標記。"
L["A deck of 100 stacks holding 2 Tempest procs."] = "一副 100 層的牌組，含 2 次暴風雨觸發。"
L["A deck of 250 stacks holding 5 Storm Unleashed procs."] = "一副 250 層的牌組，含 5 次風暴釋放觸發。"
L["A deck of 333 Maelstrom holding 2 Tempest procs."] = "一副 333 點元能的牌組，含 2 次暴風雨觸發。"
L["A deck of 333 stacks holding 2 Ascendance procs."] = "一副 333 層的牌組，含 2 次卓越術觸發。"
L["A deck of 600 Maelstrom Weapon stacks holding 3 Doom Winds procs."] = "一副 600 層氣漩武器的牌組，含 3 次末日之風觸發。"
L["A dim dark line along the edge, under the moving lines."] = "沿邊緣的一條淡淡的深色線，位於移動線條的下方。"
L["A female voice"] = "女聲"
L["A fill, like a bar"] = "像量條一樣的填充"
L["A glow around the bar, with a trigger of its own. Works in combat."] = "量條周圍的發光，有自己的觸發器。戰鬥中也有效。"
L["A grid of small tiles showing the art and the name. Click a tile to edit it. Hover it for its details, Edit and Delete."] = "由小圖塊組成的網格，顯示圖案和名稱。點擊圖塊可編輯。滑鼠指向可查看詳情、編輯和刪除。"
L["A group needs at least one column."] = "群組至少需要一欄。"
L["A group needs at least one row."] = "群組至少需要一列。"
L["A layout for 1 class"] = "適用於1個職業的版面設定"
L["A layout pack you use has a newer version."] = "你使用的某個版面設定包有了新版本。"
L["A look of its own under a time left"] = "剩餘時間低於某值時使用獨立的樣式"
L["A look under a time left"] = "剩餘時間低於某值時的樣式"
L["A male voice"] = "男聲"
L["A mark where each spell's cost is met. It shows with Tick marks on (Appearance > Ticks)."] = "在每個法術的消耗被滿足的位置顯示一個標記。開啟「刻度標記」（外觀 > 刻度）後顯示。"
L["A mark where your next spell can be queued: press it past the mark and it goes off as soon as this cast ends."] = "標出下一個法術可以排隊的位置：在標記之後按下，它會在本次施法結束時立即施放。"
L["A missing aura"] = "缺少的光環"
L["A name, version, link and notes for your pack. Whoever imports the string sees them first."] = "你的版面設定包的名稱、版本、連結和說明。匯入此字串的人會先看到這些。"
L["A named frame"] = "一個已命名的框架"
L["A nameplate: not offered"] = "名條：不提供"
L["A newer version is out: click to update your copy"] = "有新版本：點擊更新你的副本"
L["A newer version of this layout is out. Updates the layout you made from it; your own sizes and positions stay."] = "這個版面設定有了新版本。會更新你由它建立的版面設定；你自己的大小和位置會保留。"
L["A percent of the bar, or power with In power units on."] = "量條的百分比；開啟「以資源值為單位」後則為資源值。"
L["A picture of your own: its FileDataID, or its path such as Interface/AddOns/MyMedia/glow. Enter applies it; empty = pick one above."] = "你自己的圖片：其 FileDataID，或路徑，如 Interface/AddOns/MyMedia/glow。按 Enter 套用；留空 = 從上方選擇。"
L["A picture that follows an aura, a cooldown, your power, health or triggers."] = "跟隨光環、冷卻、你的資源、生命力或觸發器變化的圖片。"
L["A power bar; Automatic follows the power you are using."] = "資源條；「自動」會跟隨你正在使用的資源。"
L["A proc glow ended"] = "觸發發光已結束"
L["A proc glow started"] = "觸發發光已開始"
L["A proc shows it at full opacity"] = "觸發時以完全不透明顯示"
L["A quarter turn: the bar becomes tall and thin, and its icon, texture and gradient turn with it."] = "旋轉四分之一圈：量條變成又高又窄，圖示、材質和漸層也會跟著轉。"
L["A rank: only that one, such as a cheaper rank you queue to save mana."] = "指定一個等級：只認這一個，例如為節省法力而排隊使用的低消耗等級。"
L["A reactive ability lit up"] = "一個反應式技能亮起"
L["A reminder exported on its own joins this group. A group keeps one reminder per spell, item or weapon hand, so duplicates stay out."] = "單獨匯出的提醒會加入此群組。群組中每個法術、物品或主副手武器各只保留一個提醒，因此不會重複。"
L["A returning icon"] = "重新出現的圖示"
L["A ring of your spells and items: hold its key, point at one and let go to cast it."] = "由你的法術和物品組成的圓環：按住它的快捷鍵，指向其中一個並放開即可施放。"
L["A ring, like a cooldown"] = "像冷卻一樣的圓環"
L["A set duration"] = "固定的持續時間"
L["A share of the time"] = "時間的一定比例"
L["A short flash"] = "短暫的閃爍"
L["A short word, like %s"] = "一個簡短的詞，例如 %s"
L["A short word, like C"] = "一個簡短的詞，例如 C"
L["A short word, like D"] = "一個簡短的詞，例如 D"
L["A short word, like M"] = "一個簡短的詞，例如 M"
L["A short word, like N"] = "一個簡短的詞，例如 N"
L["A short word, like P"] = "一個簡短的詞，例如 P"
L["A skin made from the default look. A bar's Skin dropdown makes one from that bar's look."] = "由預設樣式製作的造型。量條的「造型」下拉選單會用該量條的樣式製作一個。"
L["A soft glow around the icon in this type's color. Glow size is under All."] = "圖示周圍以此類型的顏色顯示柔和的發光。發光大小在「全部」下設定。"
L["A spare profile in Arc UI: its groups and icons come in switched off; turn them on in their Load tab."] = "Arc UI 中的備用設定檔：其群組和圖示匯入時為關閉狀態；請在它們的「載入」分頁中開啟。"
L["A spark crosses the bar every 2 seconds and lands on each mana tick."] = "火花每2秒掠過量條一次，並落在每次法力回復的跳點上。"
L["A spell"] = "一個法術"
L["A spell ID, a link, or the name of a spell you know."] = "法術 ID、連結，或你已學會的法術名稱。"
L["A spell ID, a link, or the name of a spell you know. Any rank of it counts unless Only this rank is on."] = "法術 ID、連結，或你已學會的法術名稱。只要未開啟「僅此等級」，它的任何等級都算。"
L["A spell ID, a link, or the name of a spell you know. Enter applies it."] = "法術 ID、連結，或你已學會的法術名稱。按 Enter 套用。"
L["A spell ID, a spell link, or the name of a spell in your spellbook: for spells the catalog does not list."] = "法術 ID、法術連結，或你法術書中的法術名稱：用於目錄中沒有列出的法術。"
L["A spell ID, or the name of a spell you know. Any rank works: the bar follows the rank you know."] = "法術 ID，或你已學會的法術名稱。任何等級都可以：量條會跟隨你已學會的等級。"
L["A spell ID, or the name of a spell you know. It goes on the first empty spot; one you have not learned yet shows grey until you do."] = "法術 ID，或你已學會的法術名稱。它會放到第一個空位；尚未學會的法術會顯示為灰色，直到你學會為止。"
L["A spell ID, or the name of a spell you know. The rank you know is checked."] = "法術 ID，或你已學會的法術名稱。會檢查你已學會的等級。"
