L["A spell name or ID, such as Raptor Strike, Heroic Strike, Cleave or Maul. "] = "法術名稱或 ID，例如猛禽一擊、英勇打擊、順劈斬或槌擊。 "
L["A spell stopped being usable"] = "法術變為不可使用"
