L["A spend every half second, a proc at a third and two thirds of the deck, then a new deck."] = "每半秒消耗一次，在牌組的三分之一和三分之二處各觸發一次，然後開始新一副牌組。"
L["A spot mid-screen where your cooldowns pulse as they come back."] = "畫面中央的一個位置，你的技能冷卻結束時會在此脈動提示。"
L["A stance, form or aura from your stance bar. The icon lights up while you are in it."] = "你姿態列中的一個姿態、形態或光環。你處於其中時圖示會亮起。"
L["A string to share this skin."] = "用於分享這個造型的字串。"
