L["Click to choose from every picture."] = "點擊從所有圖片中選擇。"
L["Click to drop it"] = "點擊以取消"
L["Click to edit it. The eye hides it on screen while you edit, the lock keeps it from moving, the red x deletes it."] = "點擊進行編輯。眼睛圖示會在你編輯時將它從畫面上隱藏，鎖頭圖示可防止它移動，紅色 x 會將它刪除。"
L["Click to edit it. The eye hides it on screen while you edit, the red x deletes it."] = "點擊進行編輯。眼睛圖示會在你編輯時將它從畫面上隱藏，紅色 x 會將它刪除。"
L["Click to edit it. The lock keeps it from moving, the red x deletes it."] = "點擊編輯。鎖形圖示可防止它被移動，紅色 x 可刪除它。"
L["Click to edit it. The red x deletes it."] = "點擊編輯。紅色 x 可刪除它。"
L["Click to edit this icon"] = "點擊編輯此圖示"
L["Click to edit this reminder"] = "點擊編輯此提醒"
L["Click to fold the element list and give the layout settings the whole page. Drag the grip under the list to resize it."] = "點擊可收合元素清單，讓版面設定佔滿整頁。拖曳清單下方的握把可調整大小。"
L["Click to give "] = "點擊為 "
L["Click to hide this layout on screen while this window is open, so you can get at what sits under it. Closing the window shows it again."] = "點擊可在此視窗開啟期間隱藏畫面上的這個版面設定，方便你操作它下方的內容。關閉視窗後會再次顯示。"
L["Click to pick   Right-click or Esc: cancel"] = "點擊選取   按右鍵或 Esc：取消"
L["Click to pick the fill color while this row holds. Right-click to keep the bar's own."] = "點擊選擇此列生效時的填充顏色。按右鍵則保留量條自己的顏色。"
L["Click to pick the texts color while this row holds. Right-click to keep the bar's own."] = "點擊選擇此列生效時的文字顏色。按右鍵則保留量條自己的顏色。"
L["Click to pick this talent."] = "點擊選擇此天賦。"
