L["Click what %s should anchor to. Esc cancels."] = "點擊%s要錨定到的對象。按 Esc 取消。"
L["Click, then press a key or mouse button 3 to 5 (with Shift, Ctrl or Alt if you like). "] = "點擊，然後按下一個按鍵或滑鼠按鍵 3 到 5（也可搭配 Shift、Ctrl 或 Alt）。 "
L["Click, then press the key (with Shift, Ctrl or Alt if you like). "] = "點擊，然後按下該按鍵（也可搭配 Shift、Ctrl 或 Alt）。 "
