L["Emity's latest version: a Defences row, a row for trinkets, a potion, your weapon enchant and stance, a new DPS rotation row, gradient bars, and long cooldowns shown only while on cooldown."] = "Emity 的最新版本：防禦列、飾品、藥水、你的武器附魔和姿態列、新的傷害輸出循環列、漸層量條，以及僅在冷卻中顯示的長冷卻。"
