L["Emity's latest version: a Defences row, a row for trinkets, potions, mana gems, your weapon enchant and armor, gradient bars, and long cooldowns shown only while on cooldown."] = "Emity 的最新版本：防禦列、飾品、藥水、法力寶石、你的武器附魔和護甲列、漸層量條，以及僅在冷卻中顯示的長冷卻。"
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and aspect, a new rotation row, gradient bars, and long cooldowns shown only while on cooldown."] = "Emity 的最新版本：防禦列、飾品、藥水、你的武器附魔和守護列、新的輸出循環列、漸層量條，以及僅在冷卻中顯示的長冷卻。"
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and aura, Turn Undead, gradient bars, and long cooldowns shown only while on cooldown."] = "Emity 的最新版本：防禦列、飾品、藥水、你的武器附魔和光環列、超渡不死生物、漸層量條，以及僅在冷卻中顯示的長冷卻。"
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and form, more target debuffs, and long cooldowns shown only while on cooldown."] = "Emity 的最新版本：防禦列、飾品、藥水、你的武器附魔和形態列、更多目標減益效果，以及僅在冷卻中顯示的長冷卻。"
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and form, the racial priest spells, gradient bars, and long cooldowns shown only while on cooldown."] = "Emity 的最新版本：防禦列、飾品、藥水、你的武器附魔和形態列、種族牧師法術、漸層量條，以及僅在冷卻中顯示的長冷卻。"
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and soul shards, more debuffs, gradient bars, and long cooldowns shown only while on cooldown."] = "Emity 的最新版本：防禦列、飾品、藥水、你的武器附魔和靈魂裂片列、更多減益效果、漸層量條，以及僅在冷卻中顯示的長冷卻。"
