L["Hides between casts; shows a sample cast while this window is open."] = "兩次施法之間隱藏；此視窗開啟期間會顯示一次示範施法。"
L["Hides casts you cannot interrupt. In combat the game hides that from addons, so it cannot drive sounds or alerts."] = "隱藏無法中斷的施法。戰鬥中遊戲不會把這項資訊提供給插件，因此無法用來觸發音效或警示。"
L["Hides it on screen while this window is open, so you can get at what sits under it. Closing the window shows it again."] = "此視窗開啟期間在畫面上隱藏它，方便你操作它下方的內容。關閉視窗後會再次顯示。"
L["Hides the game's castbar under your character while this castbar is loaded. Turn off to bring it back on your next cast."] = "此施法條載入期間，隱藏角色下方的遊戲施法條。關閉後，下次施法時會恢復顯示。"
L["Hides the minimap button. %s always opens this window. Drag the button along the rim to move it, right-click for move mode."] = "隱藏小地圖按鈕。%s 一律可開啟此視窗。沿邊緣拖曳按鈕可移動，按右鍵可進入移動模式。"
L["Hides this update here until the next version. The tag on the layout in the sidebar stays."] = "在下個版本之前隱藏此處的這個更新。側邊欄中版面設定上的標籤仍會保留。"
L["Hides while the unit is not there; always shows while this window is open."] = "單位不存在時隱藏；此視窗開啟期間一律顯示。"
L["High threat"] = "高仇恨"
L["Highest rank"] = "最高等級"
