L["Horizontal"] = "水平"
L["Horizontal packs each row sideways; Vertical packs each column up or down."] = "「水平」會把每一列橫向排列；「垂直」會把每一欄向上或向下排列。"
L["Hot chance color"] = "高機率顏色"
L["Hot from (%)"] = "高機率起始值（%）"
L["Hover a frame on screen, a game frame or one of your Arc Auras items, and click it. Right-click or Esc cancels."] = "將滑鼠移到畫面上的某個框架（遊戲框架或你的 Arc Auras 項目）上並點擊。按右鍵或按 Esc 取消。"
L["Hover a game frame on screen and click it. Right-click or Esc cancels."] = "將滑鼠移到畫面上的某個遊戲框架上並點擊。按右鍵或 Esc 取消。"
L["Hover a game frame, an action button, a Cooldown Manager icon or an Arc Auras icon and left-click it. Right-click or Esc cancels."] = "將滑鼠移到某個遊戲框架、快捷按鈕、技能監控圖示或 Arc Auras 圖示上並按左鍵點擊。按右鍵或 Esc 取消。"
L["Hovering an icon shows its spell, item or totem tooltip."] = "滑鼠停留在圖示上時，會顯示其法術、物品或圖騰的滑鼠提示。"
L["How big the preview is against the bar's real size. Click to fit the whole bar in view again."] = "預覽相對於量條實際大小的比例。點擊可讓整條量條重新適應視野。"
L["How countdown numbers round. Up: 13.2 reads 14, like action bar cooldowns. Down: 13.2 reads 13, like buff timers and nameplates."] = "倒數數字的取整方式。向上：13.2 顯示為 14，如同快捷列冷卻。向下：13.2 顯示為 13，如同增益效果計時器和名條。"
L["How far the glow reaches past the icon: 1 sits on its edge."] = "發光向圖示外延伸的距離：1 表示緊貼圖示邊緣。"
L["How far your target is, in colored range bands you can edit."] = "你的目標有多遠，以可編輯的彩色距離區間顯示。"
L["How fast a line is spoken. 0 follows WoW's own speech rate."] = "一句話的語速。0 表示跟隨 WoW 自己的語速。"
L["How it looks in each state"] = "各狀態下的樣式"
L["How it shows"] = "顯示方式"
L["How long a flash shows. A held button keeps the highlight at least this long, so clicks that cast on release still show."] = "閃爍顯示的時間長度。按住按鈕時，醒目標示至少會維持這麼久，因此放開才施放的點擊仍會顯示。"
L["How long after that rule last fired this one may fire (Not after: may not fire). Enter applies it."] = "在那條規則上次觸發後多久，這一條才可以觸發（「不在其後」：則不可觸發）。按 Enter 套用。"
L["How long it shows after each cast."] = "每次施法後顯示多久。"
L["How long the bar takes to fade away when a cast ends (after the hold, when that is on). 0 = it goes at once."] = "施法結束後，量條淡出消失所需的時間（若開啟了保持，則在保持結束後）。0 = 立即消失。"
L["How long the button glow takes to fade when it stops. 0: it goes at once."] = "按鈕發光停止時淡出所需的時間。0：立即消失。"
L["How long the timer runs when a rule starts it with no seconds of its own. Enter applies it."] = "規則啟動計時器卻未給出秒數時，計時器執行多久。按 Enter 套用。"
L["How long the timer runs, and each stack when stacks run out on their own, when a rule gives no seconds. Enter applies it."] = "規則未給出秒數時，計時器的執行時間；層數各自到期時，則為每一層的時間。按 Enter 套用。"
L["How long the timer runs, or an added stack lasts; 0 takes the item's Default seconds. Decimals work (1.5). Enter applies it."] = "計時器執行多久，或新增的層持續多久；0 表示採用該項目的預設秒數。可以用小數（1.5）。按 Enter 套用。"
L["How long, in seconds; decimals work (1.5). Enter applies it."] = "時長，單位為秒；可以用小數（1.5）。按 Enter 套用。"
L["How many"] = "數量"
