L["On your screen"] = "在你的畫面上"
L["On: adding stacks also starts the timer over, with the seconds below."] = "開啟：增加層數時也會讓計時器重新開始，使用下方的秒數。"
L["On: every Arc Proc resets the moment a key starts, so a reset is never missed. Off: on the gate drop, which keeps the skip working."] = "開啟：每個 Arc 觸發在鑰石開始的瞬間重置，因此不會漏掉重置。關閉：在大門落下時重置，這樣略過功能仍可正常運作。"
L["On: icons pack (Show while missing ones too). Off: every aura keeps its spot."] = "開啟：圖示會緊湊排列（包括「缺少時顯示」的圖示）。關閉：每個光環都保留自己的位置。"
L["On: it glows while this look shows. Click to switch it."] = "開啟：此樣式生效期間會發光。點擊可切換。"
L["On: the debuffs start on the line after the buffs. Off: they follow straight on."] = "開啟：減益效果從增益效果之後的下一列開始。關閉：緊接著增益效果排列。"
L["On: the rule fires only while the conditions below hold. Off drops them."] = "開啟：規則僅在下方的條件成立時觸發。關閉則忽略這些條件。"
L["On: the skin sets it for every bar that wears it. Off: each bar keeps its own."] = "開啟：造型會為每個使用它的量條設定此項。關閉：每個量條保留自己的設定。"
L["On: the spell's own requirement decides (a proc, enough mana), even on cooldown. Off: only when it can be cast now."] = "開啟：由法術自身的條件決定（觸發效果、法力足夠），即使在冷卻中也一樣。關閉：僅在現在可以施放時。"
L["On: the trigger fires for your pet's casts of the spell as well as yours."] = "開啟：觸發器在你的寵物施放該法術時也會觸發，與你自己施放時一樣。"
L["On: this opacity while none is left. Off: it keeps its opacity."] = "開啟：沒有剩餘時使用此透明度。關閉：維持原有透明度。"
L["On: this opacity while toggled on. Off: it keeps its opacity."] = "開啟：切換為開啟期間使用此透明度。關閉：保持它原來的透明度。"
L["On: this trigger has its own pulse duration and animation tuning. Off drops them, and the reminder's apply."] = "開啟：此觸發器擁有自己的脈動持續時間和動畫調整。關閉則捨棄它們，改用提醒的設定。"
L["Once an ability is off cooldown."] = "技能冷卻結束後。"
L["Once the proc glow goes, the pulse this trigger started leaves the screen, the queue and the hold."] = "觸發發光消失後，此觸發器啟動的脈動會離開畫面、佇列和保持狀態。"
L["Once the spell stops being usable, the pulse this trigger started leaves the screen, the queue and the hold."] = "法術不再可使用後，此觸發器啟動的脈動會離開畫面、佇列和保持狀態。"
L["One card per element with its preview, kind, load conditions, Edit and Delete."] = "每個元素一張卡片，含其預覽、類型、載入條件、編輯和刪除。"
L["One color"] = "單一顏色"
L["One editor for every selected icon (or bar): the rows they all share, read from the first one; a change lands on all of them."] = "為所有選取的圖示（或量條）提供同一個編輯器：顯示它們共有的列，數值取自第一個；一處變更會套用到所有項目。"
L["One layer for every element of this layout, or each element's own layer moved up or down."] = "此版面設定的所有元素共用一個層級，或把每個元素自己的層級整體上移或下移。"
