L["The Active look, its timer running with its swipe and duration text. Drag any text on the icon to place it."] = "「啟用中」樣式，其計時器執行，帶轉圈和持續時間文字。拖曳圖示上的任意文字可調整其位置。"
L["The Algeth'ar Puzzle Box's haste: 20 seconds from its use; dying clears it."] = "阿爾蓋薩謎盒的加速效果：使用後持續 20 秒；死亡會清除它。"
L["The Arc Proc's own"] = "Arc 觸發自帶"
L["The Cooldown Manager look draws the border and the shadow."] = "技能監控樣式負責繪製邊框和陰影。"
L["The Cooldown Manager look sets the picture's size, crop and shape."] = "技能監控樣式決定圖片的大小、裁切和形狀。"
L["The Cooldown Manager's cooldown IDs for spells, auras and trinkets, one line per category. Runs of IDs show as ranges."] = "技能監控中法術、光環和飾品的冷卻 ID，每個類別一行。連續的 ID 會以範圍顯示。"
L["The Cooldown Manager's soft shadow frame around the icon art."] = "技能監控在圖示圖案周圍的柔和陰影框。"
L["The ID block shows only when Shift is held as the tooltip opens."] = "只有在滑鼠提示開啟時按住 Shift，才會顯示 ID 區塊。"
L["The ID of what the tooltip shows: a spell, aura, item, toy, mount, currency, achievement or quest."] = "滑鼠提示所顯示內容的 ID：法術、光環、物品、玩具、坐騎、貨幣、成就或任務。"
L["The Light's Potential potion: 30 seconds from the drink, each drink restarts it; dying clears it."] = "潛能聖水：飲用後持續 30 秒，每次飲用都會重新開始；死亡會清除它。"
L["The Not active look, with no timer running."] = "「未啟用」樣式，沒有計時器在執行。"
L["The On cooldown look: the timer idle and its cooldown spell cooling down."] = "「冷卻中」樣式：計時器閒置，其冷卻法術正在冷卻。"
L["The Ready look: the timer idle and its cooldown spell ready."] = "「就緒」樣式：計時器閒置，其冷卻法術已就緒。"
L["The Timer running look, its timer frozen with its swipe and duration text. Drag any text on the icon to place it."] = "「計時器執行中」樣式，其計時器定格，帶轉圈和持續時間文字。拖曳圖示上的任意文字可調整其位置。"
L["The Tracked Bars entry this bar copies. Keep the Cooldown Manager's own bar on, and hide it with opacity 0 in Edit Mode."] = "此量條複製的「追蹤的量條」項目。請保持技能監控自己的量條開啟，並在編輯模式中把透明度設為 0 來隱藏它。"
L["The action bar's yellow check on the icon while it waits for your next swing."] = "快捷列上圖示的黃色選取狀態，在等待你下一次揮擊期間顯示。"
L["The art's spell"] = "圖案的法術"
L["The aura at 3 stacks."] = "3 層的光環。"
L["The aura comes up with a fake duration (swipe and duration text), drops to its missing look, and comes back."] = "光環以模擬的持續時間出現（轉圈和持續時間文字），然後變為缺少樣式，再重新出現。"
L["The aura counts down, drops off, and comes back: threshold colours and the duration text."] = "光環倒數、消失，再重新出現：門檻顏色和持續時間文字。"
L["The aura icons in this group are kept for when you switch back."] = "本群組中的光環圖示會保留，以便你切換回來時使用。"
L["The aura lasts"] = "光環持續"
L["The aura lasts (seconds)"] = "光環持續（秒）"
L["The aura with 60% of its duration left."] = "剩餘 60% 持續時間的光環。"
L["The aura's full length, which the game keeps from addons: seconds need it, percent does not. 0 = not set: always shown."] = "光環的總時長，遊戲不會告知插件：秒數需要它，百分比不需要。0 = 未設定：一律顯示。"
L["The aura's full length. The game hides it from addons, so seconds thresholds need it. 0 = not set: the glow shows the whole time."] = "光環的完整持續時間。遊戲不會把它提供給插件，因此秒數門檻需要這個值。0 = 未設定：發光會全程顯示。"
L["The aura's icon"] = "光環的圖示"
L["The aura's spell ID, or the spell whose cooldown it follows: an ID, a link or the name of a spell you know. Enter applies it."] = "光環的法術 ID，或它所跟隨冷卻的法術：ID、連結或你已學會的法術名稱。按 Enter 套用。"
L["The aura's spell IDs, comma separated."] = "光環的法術 ID，以逗號分隔。"
L["The aura's spell IDs, comma separated. Any caster's copy counts."] = "光環的法術 ID，以逗號分隔。任何施放者的那份都算。"
L["The aura's spell IDs, separated by commas or spaces. Add every rank's ID if they differ. The game shows whichever is up."] = "光環的法術 ID，以逗號或空格分隔。若各等級的 ID 不同，請全部加入。遊戲會顯示目前存在的那一個。"
L["The aura's spell IDs, separated by commas or spaces. Tracking sets its unit."] = "光環的法術 ID，以逗號或空格分隔。「追蹤」決定它的單位。"
L["The aura's spell IDs, separated by commas or spaces; any of them counts."] = "光環的法術 ID，以逗號或空格分隔；其中任何一個都算。"
L["The aura's spell IDs, separated by commas or spaces; any of them shows the picture."] = "光環的法術 ID，以逗號或空格分隔；其中任何一個都會顯示圖片。"
L["The aura's spell IDs, separated by commas. A debuff usually has the ID of the spell that puts it up."] = "光環的法術 ID，以逗號分隔。減益效果通常與施加它的法術有相同的 ID。"
L["The band your target is in; blank with no target or a friendly one."] = "你的目標所在的區間；沒有目標或目標為友方時留空。"
L["The bar"] = "該量條"
L["The bar at 3 stacks, or at its Max stacks when that is lower."] = "3 層時的量條，或在「最大層數」較低時取最大層數。"
L["The bar at 60%, standing still."] = "60% 時的量條，保持靜止。"
L["The bar between swings."] = "兩次揮擊之間的量條。"
L["The bar in the middle of a cast, standing still."] = "施法進行到一半時的量條，保持靜止。"
L["The bar is full at this many stacks. Empty: the maximum the game reports, shown in the field. Type a number only if it is wrong."] = "量條在達到此層數時為滿。留空：使用遊戲回報的最大值，顯示在欄位中。僅在該值有誤時才輸入數字。"
L["The bar part way through its timer."] = "計時器進行到一半時的量條。"
L["The bar shows half the power; past the middle it fills again in the second half color."] = "量條只顯示一半的資源；過了中點後以「後半段顏色」再次填充。"
L["The bar with no timer running."] = "沒有計時器執行時的量條。"
L["The bar's look."] = "量條的樣式。"
L["The bar's own look"] = "量條自己的樣式"
L["The bars that wear it keep its look as their own."] = "使用它的量條會把它的樣式保留為自己的。"
L["The buff this totem gives you, as its tooltip names it. The Out of range look shows while the totem is out and you lack it."] = "此圖騰給予你的增益效果，名稱以其滑鼠提示為準。圖騰在場而你沒有該效果時，會顯示「超出範圍」樣式。"
L["The chance climbs 1% per Riptide since the last proc."] = "自上次觸發以來，每使用一次激流，機率上升 1%。"
L["The chance climbs per qualifying harvest; needs the 2-piece set."] = "每次符合條件的收穫都會提升機率；需要 2 件套裝效果。"
L["The chance of a proc"] = "觸發的機率"
L["The class this skin switches on for."] = "此造型為哪個職業啟用。"
L["The color %s."] = "顏色 %s。"
L["The cooldown lasts (seconds)"] = "冷卻持續時間（秒）"
L["The cooldown swipe keeps its own opacity while the icon dims, so only the art fades."] = "圖示變暗時，冷卻轉圈保持自身的透明度，只有圖案淡出。"
L["The count"] = "計數"
L["The count of your equipped ammo; blank with the slot empty."] = "你已裝備彈藥的數量；欄位為空時留空。"
L["The count the \"Ammo is low\" load and visibility condition uses. An icon's warning glow and ammo count colors have their own thresholds."] = "「彈藥不足」載入和可見度條件所使用的數量。圖示的警告發光和彈藥數量顏色有各自的門檻。"
L["The countdown stays hidden until this many seconds are left."] = "倒數在剩餘這麼多秒之前保持隱藏。"
L["The deck half drawn, with a mark where each proc landed."] = "抽到一半的牌組，每次觸發出現的位置都有標記。"
L["The dim copy stays when the picture hides: no aura, no timer, a cooldown not ready."] = "圖片隱藏時，變暗的副本會保留：沒有光環、沒有計時器、冷卻未就緒。"
L["The end of your cast that your connection's delay covers: start the next cast once the fill reaches it."] = "你的網路延遲所涵蓋的施法末段：填充到達此處後即可開始下一次施法。"
L["The fill behind this group while the options window is open; opacity 0 means none."] = "選項視窗開啟時，此群組背後的填充；透明度 0 表示無。"
L["The fill shows how many of this deck's procs are used: none, some or all. Off: the Fill color."] = "填充顯示此牌組中已使用的觸發數量：無、部分或全部。關閉：使用「填充顏色」。"
L["The first time you log in after Arc Auras updates, a window opens once with what changed in the new version."] = "在 Arc Auras 更新後首次登入時，會開啟一次視窗，說明新版本的變化。"
L["The full look starts out of combat, or after a /reload."] = "完整樣式在脫離戰鬥後，或 /reload 後開始生效。"
L["The game does not let addons match this aura type on that unit by spell ID."] = "遊戲不允許插件依法術 ID 在該單位上符合這種光環類型。"
L["The game draws it with the aura, in combat too. Buffs work on you, your pet and friendly units; debuffs on a hostile target or focus."] = "遊戲會隨光環一起繪製它，戰鬥中也一樣。增益效果適用於你、你的寵物和友方單位；減益效果適用於敵對目標或專注目標。"
L["The game frame's name, as Pick Frame shows it. Enter applies it."] = "遊戲框架的名稱，如「選取框架」所顯示的。按 Enter 套用。"
L["The game holds this frame still in combat. It moves when combat ends."] = "遊戲在戰鬥中會讓這個框架保持不動。戰鬥結束後它才會移動。"
L["The game keeps an aura's length from addons, so seconds need it. A share needs none."] = "遊戲不向插件提供光環的時長，所以秒數需要它。分享不需要。"
L["The game keeps the aura's length from addons: 0 shows the words the whole time it is up."] = "遊戲不向插件提供光環的時長：0 表示光環生效期間一直顯示這些文字。"
L["The game plays aura sounds itself, so they work in combat, for anyone's copy of the aura."] = "光環音效由遊戲自己播放，所以戰鬥中也有效，對任何人的光環都適用。"
L["The game plays it, in combat too; Load When and the gap between cues don't apply."] = "由遊戲播放，戰鬥中也一樣；「載入的條件」和提示音之間的間隔不適用。"
L["The game protects %s, so it stays free."] = "遊戲保護著 %s，因此它保持自由。"
L["The game sent a spell update"] = "遊戲發送了法術更新"
L["The game's clock, as the minimap shows it."] = "遊戲時鐘，與小地圖上顯示的一致。"
L["The game's debuff border"] = "遊戲的減益效果邊框"
L["The game's own cooldown and buff icons and bars, as in its options. Items pinned to its icons stand free until it is back on."] = "遊戲自帶的冷卻和增益效果圖示及量條，與其選項中一致。固定在其圖示上的項目會保持自由，直到它重新開啟。"
L["The game's own gold art, untinted, so the color steps aside. Intensity still applies."] = "遊戲內建的金色圖案，不著色，因此顏色選項不起作用。強度仍然生效。"
L["The global name of a frame, e.g. ElvUF_Player. A frame that does not exist counts as not there."] = "框架的全域名稱，例如 ElvUF_Player。不存在的框架視為不存在。"
L["The global name of a game frame, e.g. PlayerFrame or ElvUF_Player."] = "遊戲框架的全域名稱，例如 PlayerFrame 或 ElvUF_Player。"
L["The glow waits for combat; out of combat the bar shows without it."] = "發光等到戰鬥中才出現；脫離戰鬥時，量條不帶發光顯示。"
L["The glow waits for combat; out of combat the icon shows without it."] = "發光等到戰鬥中才出現；脫離戰鬥時，圖示不帶發光顯示。"
L["The green outline and dark fill around each group while this window is open. Nothing shows groups as in play. Name tabs still work."] = "此視窗開啟期間，每個群組周圍的綠色輪廓和深色底色。選「無」則群組會如實際遊玩時顯示。名稱標籤仍可使用。"
L["The group"] = "該群組"
L["The group takes its %s with it."] = "該群組會帶著其%s一起移動。"
L["The group's box hugs the icons that are showing; anything anchored to it moves with it."] = "群組的框體緊貼正在顯示的圖示；錨定在其上的任何內容會隨之移動。"
L["The group's point"] = "群組的點"
L["The group's spot can't be read right now. The frame moves once it can."] = "目前無法讀取群組的位置。一旦可以讀取，框架就會移動。"
L["The groups take their %s with them."] = "各群組會帶著各自的%s一起移動。"
L["The health preview: 65% health with incoming heals and shields, in your colours and texts."] = "生命力預覽：65% 生命力，含即將到來的治療和護盾，使用你的顏色和文字。"
L["The icon"] = "圖示"
L["The icon and bar previews sit on this color."] = "圖示和量條預覽以這個顏色為底。"
L["The icon as the game's Cooldown Manager draws it: its rounded corners, its border and shadow, and its swipe."] = "圖示樣式與遊戲的技能監控一致：圓角、邊框、陰影和冷卻轉圈。"
L["The icon's cooldown ID, its exact entry in the Cooldown Manager: the crosshair on an icon fills it. Empty uses the spell above."] = "圖示的冷卻 ID，即它在技能監控中的確切條目：點擊圖示上的十字準星即可填入。留空則使用上方的法術。"
L["The icon's exact entry in the Cooldown Manager; Pick Frame on an icon fills it. Empty uses the spell above."] = "圖示在技能監控中的確切條目；對圖示使用「選取框架」即可填入。留空則使用上方的法術。"
L["The icon's file ID, the base icon when an override swapped the art, and the icon the button shows when that differs."] = "圖示的檔案 ID、被覆寫替換圖案時的基礎圖示，以及與之不同時按鈕所顯示的圖示。"
L["The import did not run."] = "匯入未執行。"
L["The internal cooldown as a timer: 45 s, less with Natural Harmony."] = "以計時器顯示內建冷卻：45 秒，擁有自然和諧時更短。"
L["The item"] = "該物品"
L["The item's own stacks, before this rule acts. Empty = no such condition."] = "該物品自身的數量，在此規則生效之前。留空 = 無此條件。"
L["The item, or several: the icon shows the first one you carry and can use."] = "該物品，或多個物品：圖示顯示你攜帶且可使用的第一個。"
L["The items that used the old values take the new ones."] = "使用舊值的項目會採用新值。"
L["The items you have keep their look; only new ones start with these. Leaving the page does the same."] = "你已有的項目保留它們的樣式；只有新的項目才從這些值開始。離開頁面也有同樣效果。"
L["The kinds that take this page's rows, each where it has the row. Nothing happens until you press Copy."] = "採用此頁各列的類型，各自在擁有該列的地方生效。在你按下「複製」之前不會有任何變化。"
L["The label's own color"] = "標籤自身的顏色"
L["The layout's center point"] = "版面設定的中心點"
L["The layout's distance from the spot it's pinned to, in whole units."] = "版面設定與其固定點之間的距離，單位為整數。"
L["The line to speak."] = "要朗讀的話。"
L["The look the rows below change. The bar shows it while you edit; anything a look leaves alone follows the bar's own."] = "下方各列所修改的樣式。編輯時量條會顯示它；樣式未涉及的內容跟隨量條自己的設定。"
L["The look the rows below edit. Bar's own applies when no skin does. A skin applies when its conditions hold, first from the top."] = "下方各列所編輯的樣式。沒有造型生效時，套用「量條自身」。造型在其條件成立時生效，由上往下取第一個。"
L["The look while the aura is missing: the ghost with its Missing icon, alpha and desaturation."] = "光環缺少時的樣式：帶「缺少」圖示、透明度和去色的幽靈圖像。"
L["The look while the aura is up: Aura Active art, alpha, tint, border and glow. Drag any text to place it."] = "光環存在期間的樣式：「光環啟用中」的圖案、透明度、著色、邊框和發光。拖曳任何文字可調整位置。"
L["The look while the aura is up: its button over the cooldown, in the Aura Active look, with stacks. Drag texts to place them."] = "光環存在期間的樣式：以「光環啟用中」樣式顯示在冷卻上方的按鈕，並附上層數。拖曳文字可調整位置。"
L["The look while you are in the stance (any stance, for your current one). Drag any text on the icon to place it."] = "你處於該姿態時的樣式（選「任意姿態」時，針對你目前所處的姿態）。拖曳圖示上的任意文字可調整其位置。"
L["The look while you are not in it (no stance, for your current one)."] = "你不處於該姿態時的樣式（選「無姿態」時，針對你目前的狀態）。"
L["The mana the next tick adds glows past the fill, brightens as the tick nears, then lands. Empty while the five-second rule runs."] = "下一跳將恢復的法力會在填充之外發光，隨著這一跳臨近而變亮，然後落下。五秒規則期間為空。"
L["The middle of your screen"] = "螢幕中央"
L["The mirror is not loaded."] = "鏡像未載入。"
L["The move did not run."] = "移動未執行。"
L["The nearest band that shows, standing still."] = "顯示的最近區間，保持靜止。"
L["The new look shows after a reload"] = "新樣式將在重新載入後顯示"
L["The next tick"] = "下一跳"
L["The number beside a marker that comes back in a later swing."] = "標記旁邊的數字，該標記會在之後的某次揮擊中再次出現。"
L["The numeric item ID."] = "數字形式的物品 ID。"
L["The opacity starts with this many seconds left."] = "剩餘這麼多秒時，該透明度開始生效。"
L["The original bright cyan."] = "原本的亮青色。"
L["The pack items you deleted come back with this update. Unticked, they stay deleted."] = "你刪除的版面設定包項目會隨此更新恢復。取消勾選則保持刪除狀態。"
L["The pack's name. Whoever imports the string sees it first."] = "版面設定包的名稱。匯入此字串的人會先看到它。"
L["The part of a shield that doesn't fit past full health draws over the end of the health, so a shield on a full-health unit still shows."] = "超出滿生命力而放不下的那部分護盾會繪製在生命力量條的末端上方，因此滿血單位身上的護盾也能顯示。"
L["The picture again, dimmed, behind it: the empty part of a fill. It hides with the picture."] = "圖片再次以變暗的樣子繪製在其後方：即填充的空白部分。它隨圖片一同隱藏。"
L["The picture as it looks while active; a fill or a ring stands at 60%."] = "圖片處於啟用中的樣子；填充或圓環停在 60%。"
L["The picture grows and shrinks gently, in combat too."] = "圖片會輕輕放大縮小，戰鬥中也一樣。"
L["The picture is a sheet of frames, played in order over and over."] = "圖片是一張影格序列圖，依序循環播放。"
L["The picture keeps its shape at any width and height: its edges are cropped, never stretched."] = "無論寬高如何，圖片都保持原有形狀：邊緣會被裁切，絕不拉伸。"
L["The picture, border, swipe, shadow and glows follow the shape."] = "圖片、邊框、轉圈、陰影和發光都會跟隨該形狀。"
L["The point of the frame that goes on the group."] = "框架上要放到群組上的那個點。"
L["The power this row holds on. All powers: whatever power the bar shows."] = "此列對哪種資源生效。所有資源：量條顯示的任何資源。"
L["The pulse stays at full, with no fade, until you cast the spell or use the item, or its trigger's Clear when ends it."] = "脈動會一直保持全亮、不淡出，直到你施放法術或使用物品，或由其觸發器的「清除時機」結束它。"
L["The ready look with no animation. Drag any text on the icon to place it."] = "沒有動畫的就緒樣式。拖曳圖示上的任意文字可調整其位置。"
L["The ready look, with the Ready text when it is on."] = "就緒樣式，若開啟了「就緒」文字則一併顯示。"
L["The resize lands when you let go of the slider."] = "縮放在你放開滑桿時生效。"
L["The resource texts change color at their own power values, apart from the bar's colors."] = "資源文字依各自的資源值變色，與量條的顏色無關。"
L["The resource texts wear the fill's color, the bar's own or a row's. A row's own text color wins."] = "資源文字使用填充的顏色，即量條自身的顏色或某一列的顏色。某一列自己的文字顏色優先。"
L["The row holds for any spell left in it."] = "只要其中還剩任何法術，該列就生效。"
L["The rule fires only while this spell is off its cooldown (the GCD never counts). Empty = no such condition."] = "僅當此法術不在冷卻中時規則才會觸發（GCD 不計入）。留空 = 無此條件。"
L["The same enchant counting down, as it looks in play."] = "同一個附魔在倒數，與實際遊戲中的樣子一致。"
L["The same totem counting down, as it looks in play."] = "同一個圖騰在倒數，與實際遊戲中的樣子一致。"
L["The set gate is the Set Pieces Rule on Load Conditions."] = "套裝門檻由「載入條件」裡的「套裝部件規則」設定。"
L["The sets on the gear you wear now are listed; with fewer pieces on, the item goes inert."] = "列出你目前所穿裝備上的套裝；穿戴的部件數不足時，該物品會失效。"
L["The shield is in Appearance > Icon, the color in Appearance > Fill & Colors."] = "護盾在「外觀 > 圖示」中，顏色在「外觀 > 填充和顏色」中。"
L["The specs this skin switches on in. Pick several or Any spec."] = "此造型啟用的專精。可選多個或「任意專精」。"
L["The spell that puts it down. The bar follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "放下它的法術。量條會跟隨該圖騰或守護者，任何等級、任何欄位皆可。留空：欄位中是什麼就跟隨什麼。"
L["The spell that puts it down. The icon follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "放下它的法術。圖示會跟隨該圖騰或守護者，任何等級、任何欄位皆可。留空：欄位中是什麼就跟隨什麼。"
L["The spell that puts it down: the icon follows that totem or guardian, any rank, into whatever slot it lands."] = "放下它的法術：圖示會跟隨該圖騰或守護者，任意等級，無論落在哪個欄位。"
L["The spell that puts the totem down, any rank. Empty: this icon's spell."] = "放下圖騰的法術，任意等級。留空：使用此圖示的法術。"
L["The spell whose button or icon it rides: a spell ID, a link or the name of a spell you know. Enter applies it."] = "它所依附的按鈕或圖示對應的法術：法術 ID、連結或你已學會的法術名稱。按 Enter 套用。"
L["The spell whose button or icon it rides: an ID, a link or a known spell's name. Several ranks may be listed. Enter applies."] = "它所跟隨的按鈕或圖示所屬的法術：ID、連結或已學會的法術名稱。可列出多個等級。按 Enter 套用。"
L["The spell whose cooldown it shows. Empty: the art's spell."] = "它所顯示冷卻的法術。留空：使用圖案所屬的法術。"
L["The spell whose icon it wears. A spell ID, a link, or the name of a spell you know."] = "它所採用圖示的法術。法術 ID、連結，或你已學會的法術名稱。"
L["The spell whose icon it wears; Appearance > Icon > Art > Custom icon wins over it. A spell ID, a link, or the name of a spell you know."] = "其圖示所取自的法術；「外觀 > 圖示 > 圖案 > 自訂圖示」優先於它。可填法術 ID、連結，或你已學會的法術名稱。"
L["The spell whose range picks the band: a melee ability for Melee, a ranged spell for Caster. Empty: your class's usual one."] = "以其距離決定區間的法術：「近戰」用近戰技能，「施放者」用遠程法術。留空：使用你職業的常用法術。"
L["The spell whose range to your target decides the dim: an ID or a known spell's name. Empty: your class's usual one."] = "以其與目標的距離決定變暗的法術：ID 或已學會的法術名稱。留空：使用你職業的常用法術。"
L["The spell whose range to your target decides the rule: an ID or a known spell's name. Any rank works."] = "以其與目標的距離決定此規則的法術：ID 或已學會的法術名稱。任何等級皆可。"
L["The spell's icon"] = "法術的圖示"
L["The spell's name or ID."] = "法術的名稱或 ID。"
L["The spells it watches (any spell but these: the ones it skips), comma separated: IDs, links or names. Any rank."] = "它監視的法術（除這些以外的任何法術：即它會跳過的法術），以逗號分隔：ID、連結或名稱。任意等級。"
L["The spot on your screen the layout keeps its distance from when the resolution or UI scale changes."] = "當解析度或介面縮放改變時，版面設定與之保持距離的畫面位置。"
L["The stack count"] = "層數"
L["The stack count that fills it. 0 = the aura's most, or the custom item's Max stacks."] = "使其填滿的層數。0 = 光環的最大層數，或自訂物品的「最大層數」。"
L["The stacks"] = "層數"
L["The stacks climb to Max stacks, then clear: the fill and the count."] = "層數上升到「最大層數」後清零：填充和計數。"
L["The stacks climb to the maximum and drop: stack colours, the max colour and the count."] = "層數上升到最大值後回落：層數顏色、最大值顏色和計數。"
L["The stacks, then the timer in brackets: 3 (7.2)."] = "先是層數，然後是括號中的計時器：3 (7.2)。"
L["The stance or form you are in, or one lit while you are in it."] = "你所處的姿態或形態，或在你處於其中時亮起的那一個。"
L["The stance's spell ID: one this character does not have, such as another class's."] = "姿態的法術 ID：可以是此角色沒有的，例如其他職業的。"
L["The state that lights it: an aura up or missing, or a spell Ready, Recharging (a charge used) or On cooldown (none left)."] = "使其亮起的狀態：光環存在或缺少，或法術就緒、恢復中（已用掉一個使用次數）、冷卻中（沒有剩餘）。"
L["The swipe keeps its own opacity while Active opacity dims the icon, so only the art fades."] = "「啟用中透明度」使圖示變暗時，轉圈保持自身的透明度，只有圖案淡出。"
L["The text"] = "該文字"
L["The text to speak is set on each trigger."] = "要朗讀的文字在每個觸發器上設定。"
L["The text with a sample value, in its font, colour and box."] = "帶範例數值的文字，使用它的字型、顏色和文字框。"
L["The texture"] = "該材質"
L["The time left"] = "剩餘時間"
L["The time left on a weapon's enchant, with its charges."] = "武器附魔的剩餘時間及其使用次數。"
L["The time left on one of your totems or guardians, by the spell that puts it down or by its slot."] = "你的某個圖騰或守護者的剩餘時間，依放下它的法術或依其欄位指定。"
L["The timer"] = "計時器"
L["The timer is not running"] = "計時器未執行"
L["The timer is running"] = "計時器執行中"
L["The timer runs"] = "計時器執行"
L["The timer runs or stacks are above 0"] = "計時器執行或層數大於 0"
L["The timer runs out, rests, and starts again."] = "計時器結束，休息一會兒，然後重新開始。"
L["The top look wins when several hold."] = "多個樣式同時成立時，最上面的生效。"
L["The totem bar button this icon follows."] = "此圖示跟隨的圖騰列按鈕。"
L["The totem or guardian slot to watch. The icon lights while anything is in it."] = "要監視的圖騰或守護者欄位。欄位中有任何東西時圖示就會亮起。"
L["The totem or guardian slot to watch. The icon lights while anything is in it. A shaman's slots hold: %s."] = "要監視的圖騰或守護者欄位。欄位中有任何內容時圖示亮起。薩滿的欄位包含：%s。"
L["The tracked cooldown spell."] = "被追蹤的冷卻法術。"
L["The tracked item, or several: the icon shows the first one you carry and can use. Retargeting keeps every setting and position."] = "被追蹤的物品，可填多個：圖示顯示你攜帶且能使用的第一個。更換目標會保留所有設定和位置。"
L["The tracked spell. Retargeting re-keys the driver and keeps every setting and position."] = "被追蹤的法術。更換目標會重新綁定驅動，並保留所有設定和位置。"
L["The tracker's readout when you point at the icon. On also turns the icon's click-through off."] = "滑鼠指向圖示時顯示追蹤器的讀數。開啟時也會關閉圖示的點擊穿透。"
L["The unit's name"] = "單位的名稱"
L["The value counts power (45 energy, 2000 mana) instead of a percent of the bar."] = "該數值按資源值計（45 點能量、2000 點法力），而不是量條的百分比。"
L["The value runs from empty to full and back: threshold colours, pips and every text follow it."] = "數值從空到滿再回落：門檻顏色、分段點和所有文字都隨之變化。"
L["The wheel"] = "該轉盤"
L["The wheel is full: empty a spot first."] = "轉盤已滿：請先清空一個位置。"
L["The whole cooldown"] = "整個冷卻"
L["The whole picture"] = "整張圖片"
L["Their own class and spec checks"] = "它們自己的職業和專精檢查"
L["Their own class checks"] = "各自的職業檢查"
L["Then"] = "然後"
L["Thick line"] = "粗線"
L["Thick outline"] = "粗輪廓"
L["Thin line"] = "細線"
L["Third ammo threshold (at or below)"] = "第三個彈藥門檻（不超過）"
L["Third ammo threshold color"] = "第三個彈藥門檻顏色"
L["Third threshold (%)"] = "第三個門檻（%）"
L["Third threshold color"] = "第三個門檻顏色"
L["This %s fails its load conditions on this character (%s). You can still edit it. Click its eye to show it on screen."] = "此%s在這個角色上不符合載入條件（%s）。你仍可編輯它。點擊眼睛圖示可在畫面上顯示它。"
L["This bar doesn't load on this character (%s). Click its eye to show it while you edit."] = "此量條在這個角色上不會載入（%s）。點擊眼睛圖示，可在編輯時顯示它。"
L["This bar wears as many skins as it can."] = "此量條會盡可能多地採用造型。"
L["This bar's aura"] = "此量條的光環"
L["This bar's name"] = "此量條的名稱"
L["This bar's spell"] = "此量條的法術"
L["This character"] = "此角色"
L["This frame stops moving with the group and goes back to where it was."] = "這個框架不再隨群組移動，並回到原來的位置。"
L["This group doesn't load on this character (%s). Click its eye to show it while you edit."] = "此群組在這個角色上不會載入（%s）。點擊眼睛圖示，可在編輯時顯示它。"
L["This group follows the cursor or a nameplate. A frame can't keep up with it."] = "此群組跟隨游標或名條。框架無法跟上它。"
L["This group holds %d icons, and they would not fit. Move one out first."] = "此群組包含%d個圖示，放不下。請先移出一個。"
L["This group is not on screen, so the frame stays where it was."] = "此群組不在畫面上，所以框架保持在原來的位置。"
L["This group reminds you of it already."] = "這個群組已經在提醒你了。"
