L["This hero tree is not the one chosen."] = "這不是所選的英雄天賦樹。"
L["This icon doesn't load on this character (%s). Click its eye to show it while you edit."] = "此圖示在這個角色上不會載入（%s）。點擊眼睛圖示，可在編輯時顯示它。"
L["This icon's own rules wait until Close gaps is off: set these on the Aura Group."] = "此圖示自己的規則要等「填補空隙」關閉後才生效：請在光環群組上設定。"
