L["This layout doesn't load on this character (%s). Click its eye to show it while you edit."] = "此版面設定在這個角色上不會載入（%s）。點擊眼睛圖示，可在編輯時顯示它。"
L["This layout stops setting these. Everything that followed it goes back to its own defaults."] = "此版面設定將不再設定這些。所有跟隨它的內容都會恢復為各自的預設值。"
