L["Type a spell ID"] = "輸入法術 ID"
L["Type a spell name or ID; click a suggestion to fill it."] = "輸入法術名稱或 ID；點擊建議項即可填入。"
L["Type a spell or a cooldown ID, or pick an icon."] = "輸入法術或冷卻 ID，或選擇一個圖示。"
L["Type a spell or pick a button."] = "輸入法術或選擇一個按鈕。"
L["Type a spell: your class has no usual one for this preset."] = "請輸入法術：你的職業沒有此預設組合常用的法術。"
L["Type order"] = "類型順序"
L["Type the aura's NAME and click a spell ID, or type IDs separated by commas or spaces. The first sets the icon's art and name."] = "輸入光環的名稱並點擊一個法術 ID，或輸入以逗號或空格分隔的 ID。第一個決定圖示的圖案和名稱。"
L["Type the aura's NAME and click one of its spell IDs, or type the numeric ID and press Enter. A bar takes one ID. Settings are kept."] = "輸入光環的名稱並點擊其中一個法術 ID，或輸入數字 ID 後按 Enter。量條只接受一個 ID。設定會保留。"
L["Type the aura's NAME and click one of its spell IDs, or type the numeric ID. A bar takes one ID, the rank you cast."] = "輸入光環的名稱並點擊其中一個法術 ID，或輸入數字 ID。量條只接受一個 ID，即你施放的那個等級。"
L["Type the aura's name and click one to add its ID, or type IDs separated by commas or spaces. Any of them counts."] = "輸入光環名稱並點擊其中一個來增加其 ID，或輸入以逗號或空格分隔的 ID。其中任何一個都算。"
L["Type the aura's name and click one to add its ID, or type IDs separated by commas or spaces. Any of them lights the glow."] = "輸入光環名稱並點擊其中一個來增加其 ID，或輸入以逗號或空格分隔的 ID。其中任何一個都會點亮發光。"
L["Type the buff's NAME to see the spell IDs that carry it, then click one (every rank comes along). Add the group version's too."] = "輸入增益效果的名稱來查看帶有它的法術 ID，然後點擊其中一個（所有等級都會一併加入）。也請增加團隊版本的 ID。"
L["Type the spell ID"] = "輸入法術 ID"
L["Type the spell to check."] = "輸入要檢查的法術。"
L["Type the spell's name and click it below, or type its ID and press Enter."] = "輸入法術名稱並點擊下方的結果，或輸入其 ID 並按 Enter。"
L["Type the spell's name and click it below, or type its ID and press Enter. Any of the row's spells counts."] = "輸入法術名稱並點擊下方的結果，或輸入其 ID 並按 Enter。該列的任一法術都算。"
