L["When you learn a new rank, action bar buttons with the old top rank move up to it. Lower ranks and macros stay."] = "學會新等級時，快捷列上放著舊最高等級的按鈕會升級為新等級。較低等級和巨集保持不變。"
L["When you learn a new rank, your action bar buttons move up to it, out of combat."] = "學會新等級時，你的快捷列按鈕會在脫離戰鬥後升級為該等級。"
L["Where Position X and Y count from. Either way it moves and scales with its layout."] = "位置 X 和 Y 的計算起點。無論哪種方式，它都會隨其版面設定移動和縮放。"
L["Where a group, icon or bar shared without its layout lands. It starts on a layout that loads on this character."] = "不帶版面設定分享的群組、圖示或量條放到哪裡。預設選中一個會在此角色上載入的版面設定。"
L["Where an ability comes off cooldown: this swing, or a later one marked +1, +2."] = "技能結束冷卻的位置：本次揮擊，或標記為 +1、+2 的後續揮擊。"
L["Where an icon goes when it shows again. Only for a single row or column."] = "圖示再次顯示時所在的位置。僅適用於單列或單欄。"
L["Where each item sits (its group, or free and where), its anchor, sizes, strata and mouse. Off keeps your own placement."] = "每個項目的位置（所在的群組，或自由放置及其位置）、錨點、大小、框架層級和滑鼠互動。關閉則保留你自己的擺放。"
L["Where it sits: its edge against the group's."] = "它所處的位置：它的邊緣對著群組的邊緣。"
L["Where on the group that point goes."] = "該點放在群組上的哪個位置。"
L["Where the layout's center point (the cross on the map) sits from the spot it's pinned to, in whole pixels."] = "版面設定的中心點（地圖上的十字）與其固定點之間的距離，單位為整數像素。"
L["Where the selection goes: free in a layout, or into a group for icons. A selected group brings its icons. Press Move or Copy to apply."] = "所選項目的去向：版面設定中的自由位置，或圖示要放入的群組。選取的群組會連同其圖示一起處理。按「移動」或「複製」套用。"
L["Where they load"] = "載入位置"
L["Where this sub-panel's rows go: all of this type, one layout, one group, one item, or all icons of this kind. Press Copy to apply."] = "此子面板各列的去向：此類型的全部、一個版面設定、一個群組、一個項目，或同類的所有圖示。按「複製」套用。"
L["Where to find the pack or you, a page or a Discord. It shows as text to copy."] = "在哪裡能找到這個版面設定包或你本人，一個網頁或 Discord。它顯示為可複製的文字。"
L["Which Casts"] = "哪些施法"
L["Which of the game's volume sliders its sounds come out of."] = "它的音效通過遊戲的哪個音量滑桿輸出。"
L["Which part of each picture stays when its edges are cropped."] = "裁切邊緣時，每張圖片保留哪一部分。"
L["Which part of the picture stays when its edges are cropped."] = "裁切邊緣時，圖片保留哪一部分。"
L["Whichever lands first"] = "先到者為準"
L["While "] = "當 "
L["While %s"] = "%s期間"
L["While a charge comes back it keeps Recharging's look: can't use, not enough resource and out of range wait until it is ready."] = "使用次數恢復期間保持「恢復中」的樣式：無法使用、資源不足和超出範圍的狀態要等它就緒後才顯示。"
L["While a totem or guardian from the first spell is out, the icon shows its time instead of the aura."] = "第一個法術的圖騰或守護者存在期間，圖示顯示其時間，而不是光環。"
L["While active"] = "啟用期間"
L["While all procs are used"] = "所有觸發都已使用時"
L["While all procs used"] = "所有觸發都已使用時"
L["While an ability waits to go off with your next swing."] = "當某個技能等待隨你下一次揮擊生效時。"
L["While casting"] = "施法期間"
L["While equipped"] = "裝備期間"
L["While in stock"] = "有庫存時"
L["While it is active"] = "啟用期間"
L["While it is on cooldown"] = "冷卻期間"
L["While it is queued without the rage or mana to pay for it, the icon takes this color: that swing lands as a plain hit."] = "已排隊但沒有足夠的怒氣或法力支付時，圖示採用此顏色：那次揮擊只是普通攻擊。"
L["While it is ready"] = "就緒期間"
L["While its proc is up"] = "其觸發效果存在期間"
L["While its timer is idle it shows this spell's cooldown, then its Ready look."] = "計時器閒置時，它顯示此法術的冷卻，然後顯示其「就緒」樣式。"
L["While missing"] = "缺少期間"
L["While not active"] = "未啟用期間"
L["While on cooldown"] = "冷卻期間"
L["While out of range"] = "超出範圍期間"
L["While out of stock"] = "缺貨期間"
L["While procs are left"] = "還有觸發剩餘時"
L["While procs left"] = "還有觸發剩餘時"
L["While queued"] = "排隊期間"
L["While ready"] = "就緒期間"
L["While recharging"] = "恢復期間"
L["While suggested"] = "被推薦期間"
L["While the aura is missing"] = "光環缺少期間"
L["While the aura is up"] = "光環存在期間"
L["While the aura is up the game shows it over the icon: its time, and gone the moment it drops. Works in combat."] = "光環存在期間，遊戲會把它顯示在圖示上方：顯示其剩餘時間，光環一消失就消失。戰鬥中有效。"
L["While the aura is up, its border takes the game's color for its type: Magic, Curse, Disease or Poison. Others keep the border color."] = "光環存在期間，其邊框會使用遊戲為該類型指定的顏色：魔法、詛咒、疾病或毒。其他類型則維持邊框顏色。"
L["While the aura is up, only once little time is left, only while the aura is missing, or always. Works in combat."] = "光環存在期間、僅在剩餘時間不多時、僅在光環缺少期間，或一律。戰鬥中有效。"
L["While the button is held"] = "按住按鈕期間"
L["While the timer is idle at 0 stacks, the count shows this many: a pool reads full before its first use. Empty = off."] = "計時器在 0 層閒置時，計數顯示這個數量：資源池在首次使用前讀數為滿。留空 = 關閉。"
L["While the timer runs"] = "計時器執行期間"
L["While this bar is not loaded, its count stops until the next reset."] = "此量條未載入期間，其計數會停止，直到下次重置。"
L["While this icon is not loaded, its count stops until the next reset."] = "此圖示未載入期間，其計數會停止，直到下次重置。"
L["While this window is open a dim icon marks the spot; drag its name tab to move it."] = "此視窗開啟時，一個變暗的圖示標出位置；拖曳其名稱分頁可移動它。"
L["While this window is open the outline marks the spot; drag its name tab to move it."] = "此視窗開啟時，輪廓標出位置；拖曳其名稱分頁可移動它。"
L["While this window is open, a dim copy of the first reminder's icon marks where pulses land. On shows only the outline and name tab."] = "此視窗開啟時，第一個提醒圖示的變暗副本會標出脈動出現的位置。開啟時只顯示輪廓和名稱分頁。"
L["While this window is open, drag this item's texts where they sit on screen. X and Y follow."] = "此視窗開啟時，可在螢幕上拖曳此項目的文字到所需位置。X 和 Y 隨之更新。"
L["While this window is open, each group shows its name on its top edge, which you drag it by. Off: a small green handle, name on hover."] = "此視窗開啟期間，每個群組會在上緣顯示名稱，可拖曳名稱來移動群組。關閉：顯示綠色小把手，滑鼠指向時才顯示名稱。"
L["While this window is open, icons and bars carry a small Edit button that opens them here. Pick which kind shows it, or none."] = "此視窗開啟期間，圖示和量條上會帶有一個小的編輯按鈕，點擊即可在此開啟。選擇哪一種要顯示，或都不顯示。"
L["While this window is open, items that fail their load conditions are drawn anyway, so you can place and style them."] = "此視窗開啟期間，不符合載入條件的項目仍會顯示，讓你可以放置並調整它們的樣式。"
L["While this window is open, the group you edit shows edge arrows: green adds a row or column on that side, red removes one."] = "此視窗開啟期間，你正在編輯的群組會顯示邊緣箭頭：綠色在該側增加一列或一欄，紅色則移除一列或一欄。"
L["While toggled on"] = "切換為開啟期間"
L["Who carries the aura. Buffs match on friends and you, debuffs on enemies."] = "誰攜帶該光環。增益效果符合友方和你自己，減益效果符合敵人。"
L["Who carries the aura: a buff on you, a debuff on your target, or another unit."] = "誰攜帶該光環：你身上的增益效果、你目標身上的減益效果，或其他單位。"
L["Who carries the aura: buffs on you, your pet, party and friends, debuffs on enemies. The game hides the opposite from addons."] = "誰帶有該光環：你、你的寵物、隊伍和友方身上的增益效果，敵人身上的減益效果。遊戲不會把相反情況的資訊提供給插件。"
L["Who carries the aura: you for a buff, your target for a debuff. You, then your target: you first. Other combinations stay dark."] = "誰帶有該光環：增益效果看你自己，減益效果看你的目標。你，然後目標：先看你。其他組合不會亮起。"
L["Whole shards only"] = "僅整顆裂片"
L["Whose aura"] = "誰的光環"
L["Whose casts"] = "誰的施法"
L["Wide (3:2)"] = "寬（3:2）"
L["Width"] = "寬度"
L["Width (0 = auto)"] = "寬度（0 = 自動）"
L["Windfury Totem"] = "風怒圖騰"
L["Windfury Weapon"] = "風怒武器"
L["Wing Clip for melee, then Auto Shot with the 10 and 20 yard checks."] = "近戰用摔絆，然後是自動射擊，帶 10 碼和 20 碼檢查。"
L["Wing Clip for melee, then Auto Shot with the 20 yard check."] = "近戰用摔絆，然後是自動射擊，帶 20 碼檢查。"
L["Wins over the rows below it."] = "優先於其下方的列。"
L["With"] = "剩餘"
L["With "] = "擁有 "
L["With %s"] = "擁有 %s"
L["With %s left. Click to change it."] = "剩餘 %s。點擊可變更。"
L["With Close gaps on, set these on the Aura Group."] = "開啟「填補空隙」後，請在光環群組上設定這些。"
L["With Close gaps on, the game places the row: these apply only while this window is open."] = "開啟「填補空隙」後，由遊戲安排該列：這些設定僅在此視窗開啟時生效。"
L["With a two-hander, a shield or nothing in this hand, the icon doesn't load. It comes back when you equip a weapon there."] = "此手持有雙手武器、盾牌或什麼都沒有時，圖示不會載入。在那裡裝備武器後會恢復。"
L["With both aura types, or on nameplates, it shows as Colors and badges."] = "同時選擇兩種光環類型，或在名條上時，顯示為「顏色和徽章」。"
L["With both, the hide list applies to the buffs only."] = "同時選擇兩者時，隱藏清單只作用於增益效果。"
L["With both, the hide list applies to the debuffs only."] = "同時選擇兩者時，隱藏清單只作用於減益效果。"
L["With more than one row and column, a returning icon always takes its spot back."] = "列和欄都多於一個時，返回的圖示總會奪回原位。"
