L["Without %s"] = "沒有 %s"
L["WoW Forever"] = "WoW Forever"
L["WoW Forever: follows the rank you currently know, by name, so a new rank needs no new ID. Off: tracks the exact ID above."] = "WoW Forever：依名稱跟隨你目前已學會的等級，因此新等級不需要新 ID。關閉：追蹤上方的確切 ID。"
L["WoW's own option: a short tick when a spoken line ends."] = "WoW 自帶選項：語音結束時發出一聲短促的提示音。"
L["WoW's own text to speech volume, so it also sets chat narration."] = "WoW 自己的文字轉語音音量，因此也會設定聊天朗讀的音量。"
L["WoW's voice"] = "WoW 語音"
L["WoW's voice is the one picked in WoW's own options. Male or female picks a matching voice from your system's list."] = "「WoW 語音」是在 WoW 自己的選項中選定的那個。男聲或女聲會從你系統的清單中選取符合的語音。"
L["Wobble"] = "搖晃"
