L["Words after the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "數值之後的文字。對遊戲繪製的倒數（法術或光環的剩餘時間）無效。"
L["Words before the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "數值之前的文字。對遊戲繪製的倒數（法術或光環的剩餘時間）無效。"
L["Words you type"] = "你輸入的文字"
L["Writes each element's name over its box, here and while you move the layout on screen."] = "在每個元素的方框上寫出其名稱，在此處以及你在畫面上移動版面設定時都會顯示。"
