L["Your Arcane Blast stacks: up to 4, each cast restarts their 8 seconds; any other spell or dying clears them."] = "你的秘法衝擊層數：最多 4 層，每次施放都會讓它們的 8 秒重新開始；施放任何其他法術或死亡會清除它們。"
L["Your Casts"] = "你的施法"
L["Your Cooldown Manager could not be read just now. Try again in a moment."] = "剛才無法讀取你的技能監控。請稍後再試。"
L["Your Cooldown Manager layout is ready. Turn off the game's own Cooldown Manager now?\n\n"] = "你的技能監控版面設定已準備好。要現在關閉遊戲自帶的技能監控嗎？\n\n"
L["Your Cooldown Manager layout is ready. Turn off the game's own Cooldown Manager now?\n\nSettings > Cooldown Manager turns it back on."] = "你的技能監控版面設定已就緒。現在關閉遊戲內建的技能監控嗎？\n\n在「設定 > 技能監控」中可重新開啟。"
L["Your Cooldown Manager lists no auras here."] = "你的技能監控在這裡沒有列出任何光環。"
