L["Your Cooldown Manager's bars as groups: same spells, sizes and places. Then hide its bars in Edit Mode."] = "把你技能監控的量條變成群組：法術、大小和位置都相同。然後在編輯模式中隱藏它的量條。"
L["Your Masque skins on Arc Auras icons, aura icons included: pick one per icon group in Masque."] = "把你的 Masque 造型用在 Arc Auras 圖示上，包括光環圖示：在 Masque 中為每個圖示群組選擇一個。"
L["Your Tracked Bars are empty: add the entry to them in the Cooldown Manager first."] = "你的「追蹤的量條」是空的：請先在技能監控中把該條目增加進去。"
