L["Your current stance"] = "你目前的姿態"
L["Your current stance: the stance, form or aura you are in, greyed while in none. One stance: that one, lit while you are in it."] = "你目前的姿態：你所處的姿態、形態或光環，不處於任何一種時顯示為灰色。單個姿態：就是那一個，處於其中時亮起。"
L["Your default"] = "你的預設值"
L["Your eight trackings, in the order you learn them."] = "你的八種追蹤技能，依你學會的順序排列。"
L["Your equipped ammo and its count."] = "你已裝備的彈藥及其數量。"
L["Your fire trap, Immolation or Explosive: 60 seconds from laying it, then its burn on your target, its cooldown and Ready."] = "你的火系陷阱（獻祭陷阱或爆炸陷阱）：放置後 60 秒，然後是它對你目標的灼燒、它的冷卻和就緒。"
L["Your focus"] = "你的專注目標"
L["Your frost trap, Freezing or Ice: 60 seconds from laying it, then its effect on your target, its cooldown and Ready."] = "你的冰系陷阱（冰凍陷阱或寒冰陷阱）：放置後 60 秒，然後是它對你目標的效果、它的冷卻和就緒。"
L["Your gear's item level, as each game reports it. After the name reads Name (34); under the name adds an Item Level line."] = "你的裝備物品等級，以遊戲各自的回報為準。選「名稱之後」顯示為 名稱 (34)；選「名稱下方」則增加一行物品等級。"
